CNFWideClausePacking:
∃ pack : List Bool → List Bool,
      PEqualNP.Library.ComputableInPolyTime (fun x : List Bool => x) (fun x : List Bool => x) pack ∧
      ∀ φ : PEqualNP.Search.CNF,
        let small := PEqualNP.Search.encodeCNF ((φ.filter (fun c => c.length ≤ 2)).reverse)
        let wide := PEqualNP.Search.encodeCNF ((φ.filter (fun c => 2 < c.length)).reverse)
        pack (PEqualNP.Search.encodeCNF φ) = List.replicate small.length true ++ false :: (small ++ wide)
